<div class="section-head"><div><span class="blog-eyebrow">CONTENT STUDIO</span><h1>บทความ Blog</h1><p>จัดการเรื่องราวและแรงบันดาลใจในการเดินทาง</p></div><a class="btn" href="<?= base_url().'admin/blog/new' ?>">＋ เขียนบทความใหม่</a></div>
<nav class="blog-tabs" aria-label="สถานะบทความ"><?php foreach ([''=>'ทั้งหมด','published'=>'เผยแพร่แล้ว','draft'=>'ฉบับร่าง','trash'=>'ถังขยะ'] as $key=>$label): ?><a class="<?= $filters['status']===$key ? 'active' : '' ?>" href="<?= base_url().'admin/blog'.($key ? '?status='.$key : '') ?>"><?= $label ?> <b><?= $key ? $counts[$key] : $counts['draft']+$counts['published'] ?></b></a><?php endforeach ?><a href="<?= base_url().'admin/blog/categories' ?>">จัดการหมวดหมู่ ↗</a></nav>
<form class="blog-filters" method="get"><input type="hidden" name="status" value="<?= e($filters['status']) ?>"><label class="blog-search">ค้นหาบทความ<input name="q" value="<?= e($filters['q']) ?>" placeholder="ชื่อบทความหรือแท็ก"></label><label>หมวดหมู่<select name="category"><option value="">ทุกหมวดหมู่</option><?php foreach ($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)$filters['category']===(string)$c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></label><button class="btn" type="submit">ค้นหา</button></form>
<div class="panel blog-table-wrap"><table class="blog-table"><thead><tr><th>บทความ</th><th>หมวดหมู่ / ผู้เขียน</th><th>สถานะ</th><th>แก้ไขล่าสุด</th><th>จัดการ</th></tr></thead><tbody><?php foreach ($posts as $p): ?><tr><td><div class="blog-row-title"><img src="<?= e(tour_image($p['cover'])) ?>" alt=""><div><strong><?= e($p['title']) ?></strong><small>/blog/<?= e($p['slug']) ?></small></div></div></td><td><?= e($p['category_name'] ?: 'ไม่มีหมวดหมู่') ?><small><?= e($p['author']) ?></small></td><td><span class="blog-status <?= e($p['status']) ?>"><?= $p['status']==='trash' ? 'ถังขยะ' : status_label($p['status']) ?></span></td><td><?= thai_date($p['updated_at']) ?></td><td><div class="blog-actions"><?php if ($p['status']!=='trash'): ?><a href="<?= base_url().'admin/blog/'.$p['id'] ?>">แก้ไข</a><a href="<?= base_url().'admin/blog/'.$p['id'].'/preview' ?>" target="_blank" rel="noopener">ตัวอย่าง ↗</a><?php endif ?><form method="post" action="<?= base_url().'admin/blog/'.$p['id'].'/state' ?>" <?= $p['status']!=='trash' ? 'data-blog-confirm="ย้ายบทความนี้ไปถังขยะ? บทความจะหยุดเผยแพร่ทันที"' : '' ?>><?= csrf_field() ?><input type="hidden" name="action" value="<?= $p['status']==='trash' ? 'restore' : 'trash' ?>"><button class="text-button" type="submit"><?= $p['status']==='trash' ? 'กู้คืน' : 'ถังขยะ' ?></button></form></div></td></tr><?php endforeach ?><?php if (!$posts): ?><tr><td colspan="5"><div class="blog-empty"><h2>ยังไม่มีบทความในรายการนี้</h2><p>เริ่มเขียนเรื่องราวใหม่ หรือเปลี่ยนตัวกรองการค้นหา</p></div></td></tr><?php endif ?></tbody></table></div><?php load_view('blog/pagination'); ?>
